import { agentNativePath } from "./api-path.js";
import { agentNativeApiDisabledReason } from "./api-surface.js";
const RESULT_TTL_MS = 500;
const REQUEST_TIMEOUT_MS = 15_000;
const cache = new Map();
const requests = new Map();
const requestControllers = new Map();
const requestGenerations = new Map();
let invalidationListenersInstalled = false;
let generation = 0;
function expireClientStatusCache() {
    generation += 1;
    cache.clear();
}
function installInvalidationListeners() {
    if (invalidationListenersInstalled ||
        typeof window === "undefined" ||
        typeof document === "undefined") {
        return;
    }
    invalidationListenersInstalled = true;
    if (typeof window.addEventListener === "function") {
        window.addEventListener("focus", expireClientStatusCache);
        window.addEventListener("agent-engine:configured-changed", invalidateClientStatusRequests);
    }
    if (typeof document.addEventListener === "function") {
        document.addEventListener("visibilitychange", () => {
            if (document.visibilityState === "visible") {
                expireClientStatusCache();
            }
        });
    }
}
async function fetchClientStatus(path) {
    // "unavailable" rather than a fabricated payload: callers already treat it as
    // "could not read", and there is genuinely nothing to read here.
    if (agentNativeApiDisabledReason())
        return { state: "unavailable" };
    installInvalidationListeners();
    const url = agentNativePath(path);
    const cached = cache.get(url);
    if (cached && cached.expiresAt > Date.now()) {
        return cached.result;
    }
    cache.delete(url);
    const pending = requests.get(url);
    if (pending)
        return pending;
    const requestGeneration = generation;
    const requestUrlGeneration = requestGenerations.get(url) ?? 0;
    const controller = typeof AbortController === "undefined" ? null : new AbortController();
    let timeoutId;
    const timeout = new Promise((resolve) => {
        timeoutId = setTimeout(() => {
            controller?.abort();
            resolve({ state: "unavailable" });
        }, REQUEST_TIMEOUT_MS);
    });
    const transport = fetch(url, {
        cache: "no-store",
        credentials: "same-origin",
        ...(controller ? { signal: controller.signal } : {}),
    })
        .then(async (response) => {
        if (!response.ok) {
            return { state: "unavailable", status: response.status };
        }
        try {
            return { state: "available", value: await response.json() };
        }
        catch {
            return { state: "unavailable", status: response.status };
        }
    })
        .catch(() => ({ state: "unavailable" }));
    const request = Promise.race([transport, timeout])
        .then((result) => {
        if (generation === requestGeneration &&
            (requestGenerations.get(url) ?? 0) === requestUrlGeneration &&
            result.state === "available") {
            cache.set(url, {
                expiresAt: Date.now() + RESULT_TTL_MS,
                result,
            });
        }
        return result;
    })
        .finally(() => {
        if (timeoutId !== undefined)
            clearTimeout(timeoutId);
        if (requests.get(url) === request)
            requests.delete(url);
        if (requestControllers.get(url) === controller) {
            requestControllers.delete(url);
        }
    });
    requests.set(url, request);
    if (controller)
        requestControllers.set(url, controller);
    return request;
}
export function invalidateClientStatusRequest(path) {
    const url = agentNativePath(path);
    requestGenerations.set(url, (requestGenerations.get(url) ?? 0) + 1);
    cache.delete(url);
    requestControllers.get(url)?.abort();
    requestControllers.delete(url);
    requests.delete(url);
}
export function invalidateClientStatusRequests() {
    generation += 1;
    cache.clear();
    for (const controller of requestControllers.values()) {
        controller.abort();
    }
    requestControllers.clear();
    requests.clear();
}
export function fetchAgentEngineStatus() {
    return fetchClientStatus("/_agent-native/agent-engine/status");
}
export function fetchEnvironmentStatus() {
    return fetchClientStatus("/_agent-native/env-status");
}
export function fetchBuilderStatus() {
    return fetchClientStatus("/_agent-native/builder/status");
}
export function fetchAuthSessionStatus() {
    return fetchClientStatus("/_agent-native/auth/session");
}
